describe('Inline Editing on Table Row', () => {
  beforeEach(() => {
    cy.visit('/table');
  });

  it('should enable inline editing on table row and update data without modal', () => {
    // Verify table is visible
    cy.get('[data-testid="table-container"]').should('be.visible');

    // Get the first row
    cy.get('[data-testid="table-row-1"]').should('be.visible');

    // Verify initial data is displayed
    cy.get('[data-testid="table-row-1"]').should('contain', 'John Doe');
    cy.get('[data-testid="table-row-1"]').should('contain', 'john@example.com');

    // Click on the edit icon to enable inline editing
    cy.get('[data-testid="edit-icon-1"]').click();

    // Verify edit mode is active
    cy.get('[data-testid="table-row-1"]').should('have.class', 'edit-mode');

    // Verify input fields are visible
    cy.get('[data-testid="edit-name-1"]').should('be.visible');
    cy.get('[data-testid="edit-email-1"]').should('be.visible');

    // Fill in new data
    cy.get('[data-testid="edit-name-1"]').type('Jane Smith');
    cy.get('[data-testid="edit-email-1"]').type('jane.smith@example.com');

    // Click the save button to update
    cy.get('[data-testid="save-button-1"]').click();

    // Verify inline editing is closed
    cy.get('[data-testid="table-row-1"]').should('not.have.class', 'edit-mode');

    // Verify updated data is displayed
    cy.get('[data-testid="table-row-1"]').should('contain', 'Jane Smith');
    cy.get('[data-testid="table-row-1"]').should('contain', 'jane.smith@example.com');

    // Verify no modal is displayed
    cy.get('[data-testid="modal-container"]').should('not.exist');
  });

  it('should handle invalid input and display error message without modal', () => {
    // Get the first row
    cy.get('[data-testid="table-row-1"]').should('be.visible');

    // Click on the edit icon
    cy.get('[data-testid="edit-icon-1"]').click();

    // Verify edit mode is active
    cy.get('[data-testid="table-row-1"]').should('have.class', 'edit-mode');

    // Fill in invalid data
    cy.get('[data-testid="edit-name-1"]').type('John');
    cy.get('[data-testid="edit-email-1"]').type('invalid-email');

    // Click the save button
    cy.get('[data-testid="save-button-1"]').click();

    // Verify inline editing is closed
    cy.get('[data-testid="table-row-1"]').should('not.have.class', 'edit-mode');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Please enter a valid email address');

    // Verify no modal is displayed
    cy.get('[data-testid="modal-container"]').should('not.exist');
  });
});
